check_code:
T=[{'TL':'sq','TR':'dn','C':'tri','BL':'up','BR':'o'},{'TL':'tri','TR':'dn','C':'o','BL':'up','BR':'sq'},
{'TL':'tri','TR':'o','C':'up','BL':'dn','BR':'sq'},{'TL':'up','TR':'o','C':'sq','BL':'dn','BR':'tri'}]
odd={'TL':'BR','BR':'C','C':'TL','TR':'TR','BL':'BL'}
even={'C':'TR','TR':'BL','BL':'C','TL':'TL','BR':'BR'}
st=lambda f,r:{r[k]:v for k,v in f.items()}
assert st(T[0],odd)==T[1] and st(T[1],even)==T[2] and st(T[2],odd)==T[3]
F5=st(T[3],even)
opts={'A':{'TL':'o','TR':'tri','C':'up','BL':'sq','BR':'dn'},'B':{'TL':'up','TR':'sq','C':'dn','BL':'o','BR':'tri'},
'C':{'TL':'dn','TR':'sq','C':'up','BL':'o','BR':'tri'},'D':{'TL':'tri','TR':'o','C':'dn','BL':'sq','BR':'up'}}
assert [k for k in opts if opts[k]==F5]==['B']
